import type { Metadata } from "next";
import { siteConfig } from "@/data/site";

type PageSeo = {
  /** Page title (the root layout appends " | Leaflow"). */
  title: string;
  description: string;
  /** Route path, e.g. "/pricing". Used for the canonical and og:url. */
  path: string;
  keywords?: string[];
};

/** Shared social card generated by app/opengraph-image.tsx. */
const ogImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${siteConfig.name} — online accounting for freelancers & small businesses`,
};

/**
 * Builds per-page metadata. Without this, subpages inherit the homepage's
 * og:url / og:title, so every page would be shared as the homepage.
 */
export function pageMetadata({ title, description, path, keywords }: PageSeo): Metadata {
  const fullTitle = `${title} | ${siteConfig.name}`;
  return {
    title,
    description,
    keywords,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      url: path,
      siteName: siteConfig.name,
      title: fullTitle,
      description,
      locale: siteConfig.locale,
      images: [ogImage],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [ogImage.url],
    },
  };
}
